SELECT * FROM (SELECT g.*, RANK() OVER (ORDER BY PageViews DESC) AS rnk FROM (SELECT Title, COUNT(*) AS PageViews FROM hits WHERE CounterID = 62 AND EventDate >= '2013-07-01' AND EventDate <= '2013-07-31' AND DontCountHits = 0 AND IsRefresh = 0 AND Title <> '' GROUP BY Title) g) ranked WHERE rnk <= 10 ORDER BY rnk;
